# owner: platform
import unittest

from hourglass.rounding import round_labels
from hourglass.models import Span


class RoundLabelTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        spans = [Span(8 * 60 + 58, 17 * 60 + 14)]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_several_spans(self):
        spans = [Span(0, 60), Span(61, 1440)]
        self.assertEqual(
            round_labels(spans, 5),
            ["00:00-01:00 (1h 0m)", "01:00-24:00 (23h 0m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)


if __name__ == "__main__":
    unittest.main()
